 "content": "from collections import deque

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if g[r][c] == 8 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and g[ny][nx] != 8 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            r0, r1 = min(y for y,x in cells), max(y for y,x in cells)
            c0, c1 = min(x for y,x in cells), max(x for y,x in cells)
            colored = [(y,x) for y,x in cells if g[y][x] not in (0,8)]
            if not colored:
                continue
            tr0, tr1 = min(y for y,x in colored), max(y for y,x in colored)
            tc0, tc1 = min(x for y,x in colored), max(x for y,x in colored)
            tile = [row[tc0:tc1+1] for row in g[tr0:tr1+1]]
            th, tw = len(tile), len(tile[0])
            for y in range(r0, r1+1):
                for x in range(c0, c1+1):
                    g[y][x] = tile[(y-r0) % th][(x-c0) % tw]
    return g
